/**
 * Generates TypeScript types and standalone validators from the JSON Schemas
 * in /schemas. Run `npm run schemas` after editing a schema; CI runs
 * `npm run schemas -- --check` to make sure the generated files are current.
 */
import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import Ajv from 'ajv';
import standaloneCode from 'ajv/dist/standalone/index.js';
import { compile } from 'json-schema-to-typescript';
import { format, resolveConfig } from 'prettier';

const root = resolve(import.meta.dirname, '..');
const check = process.argv.includes('--check');
const BANNER = '// Generated by tools/schemas.ts from /schemas. Do not edit by hand.\n';

async function loadSchema(name: string) {
  return JSON.parse(await readFile(resolve(root, 'schemas', name), 'utf8')) as Record<
    string,
    unknown
  >;
}

async function pretty(code: string, filepath: string) {
  const config = (await resolveConfig(filepath)) ?? {};
  return format(code, { ...config, filepath, plugins: [] });
}

async function main() {
  const exam = await loadSchema('exam.schema.json');
  const manifest = await loadSchema('manifest.schema.json');

  const options = {
    bannerComment: '',
    additionalProperties: false,
    // Plain arrays instead of tuple types for minItems; ajv still enforces the minimum.
    ignoreMinAndMaxItems: true,
    unreachableDefinitions: true,
  } as const;
  const types =
    BANNER +
    (await compile(exam, 'Exam', options)) +
    '\n' +
    (await compile(manifest, 'Manifest', options))
      // Both schemas define Slug; keep the first declaration only.
      .replace(/export type Slug = string;\n/, '');

  const ajv = new Ajv({
    code: { source: true, esm: true, optimize: true, lines: false },
    allErrors: false,
    inlineRefs: false,
    messages: true,
    strict: true,
  });
  ajv.addSchema(exam, 'exam').addSchema(manifest, 'manifest');
  const validators =
    BANNER +
    '// @ts-nocheck\n' +
    standaloneCode(ajv, { validateExam: 'exam', validateManifest: 'manifest' }).replace(
      // Ajv emits a CommonJS require for string lengths; inline it to keep the module pure ESM.
      /const (\w+) = require\(["']ajv\/dist\/runtime\/ucs2length["']\)\.default;/,
      'const $1 = (s) => Array.from(s).length;',
    );

  const outputs = [
    [resolve(root, 'src/content/schema.types.ts'), types],
    [resolve(root, 'src/content/schema.validators.js'), validators],
  ] as const;

  let stale = false;
  for (const [file, raw] of outputs) {
    const code = await pretty(raw, file);
    const current = await readFile(file, 'utf8').catch(() => '');
    if (current === code) continue;
    if (check) {
      console.error(`Out of date: ${file}. Run "npm run schemas".`);
      stale = true;
    } else {
      await writeFile(file, code);
      console.log(`Wrote ${file}`);
    }
  }
  if (stale) process.exit(1);
}

await main();
